def upgrade():
    bind = op.get_bind()
    dialect_name = getattr(getattr(bind, "dialect", None), "name", "")
    if dialect_name != "postgresql":
        return

    # 1. Permanently archive duplicates
    op.execute(sa.text("""
        UPDATE ingestion_players
        SET real_player_tier = 'archived_duplicate',
            is_tradable = false,
            is_real_player = false,
            legendary_profile_id = NULL,
            updated_at = NOW()
        WHERE id = ANY(:dup_ids);
    """).bindparams(dup_ids=DUPLICATE_IDS))

    op.execute(sa.text("""
        UPDATE player_share_markets
        SET status = 'retired',
            total_shares = 0,
            released_shares = 0,
            circulating_shares = 0,
            updated_at = NOW()
        WHERE player_id = ANY(:dup_ids);
    """).bindparams(dup_ids=DUPLICATE_IDS))

    op.execute(sa.text("""
        DELETE FROM player_summary_read_models
        WHERE player_id = ANY(:dup_ids);
    """).bindparams(dup_ids=DUPLICATE_IDS))

    # 2. Govern active superstars (Harry Kane, Mbappé, Bellingham, Vinícius, Rodri, Courtois)
    op.execute(sa.text("""
        UPDATE ingestion_players
        SET real_player_tier = CASE WHEN COALESCE(governed_gsi, 80) >= 85 THEN 'marquee' ELSE 'established' END,
            legendary_profile_id = NULL,
            is_tradable = true,
            is_real_player = true,
            updated_at = NOW()
        WHERE id = ANY(:active_ids);
    """).bindparams(active_ids=ACTIVE_STAR_IDS))

    op.execute(sa.text("""
        UPDATE player_share_markets
        SET status = 'active',
            total_shares = 200,
            released_shares = 200,
            updated_at = NOW()
        WHERE player_id = ANY(:active_ids);
    """).bindparams(active_ids=ACTIVE_STAR_IDS))

    op.execute(sa.text("""
        UPDATE player_summary_read_models rm
        SET summary_json = (
            COALESCE(rm.summary_json::jsonb, '{}'::jsonb) || jsonb_build_object(
                'real_player_tier', ip.real_player_tier,
                'is_legend', false,
                'total_shares', 200,
                'released_shares', 200,
                'is_tradable', true
            )
        )::json,
        updated_at = NOW()
        FROM ingestion_players ip
        WHERE rm.player_id = ip.id
          AND ip.id = ANY(:active_ids);
    """).bindparams(active_ids=ACTIVE_STAR_IDS))

    # 3. Ensure real_player_tier = 'legend' for all authentic legends
    all_legend_ids = [item[0] for item in LEGEND_UPDATES]
    op.execute(sa.text("""
        UPDATE ingestion_players
        SET real_player_tier = 'legend',
            is_tradable = true,
            is_real_player = true,
            updated_at = NOW()
        WHERE id = ANY(:legend_ids);
    """).bindparams(legend_ids=all_legend_ids))

    # 4. Calibrate GSI ratings and DNA profile for all authentic legends
    values_clause = ", ".join(f"('{pid}'::text, {gsi})" for pid, gsi in LEGEND_UPDATES)
    op.execute(f"""
        UPDATE ingestion_players AS ip
        SET governed_gsi = v.gsi,
            governed_potential_gsi = v.gsi,
            gsi_override_reason = 'governed_legend_calibrated_v3',
            dna_profile = jsonb_set(
                jsonb_set(
                    jsonb_set(
                        jsonb_set(COALESCE(ip.dna_profile::jsonb, '{{}}'::jsonb), '{{overall}}', to_jsonb(v.gsi)),
                        '{{current_rating}}', to_jsonb(v.gsi)
                    ),
                    '{{potential}}', to_jsonb(v.gsi)
                ),
                '{{potential_rating}}', to_jsonb(v.gsi)
            )::json,
            updated_at = NOW()
        FROM (VALUES {values_clause}) AS v(id, gsi)
        WHERE ip.id = v.id;
    """)

    # 5. Sync linked legendary_player_profiles
    op.execute("""
        UPDATE legendary_player_profiles lpp
        SET governed_gsi = ip.governed_gsi,
            governed_potential_gsi = ip.governed_gsi,
            is_active = true,
            is_searchable = true,
            is_tradable = true,
            updated_at = NOW()
        FROM ingestion_players ip
        WHERE ip.legendary_profile_id = lpp.id
          AND ip.real_player_tier = 'legend';
    """)

    # 6. Ensure player_share_markets has 1 unit for all legends
    op.execute("""
        INSERT INTO player_share_markets (
            player_id, total_shares, released_shares, circulating_shares,
            share_price_coin, status, created_at, updated_at
        )
        SELECT 
            ip.id, 1, 1, 0,
            ROUND(250.0 * POWER(ip.governed_gsi / 90.0, 3.2) * 3.6, 2),
            'active', NOW(), NOW()
        FROM ingestion_players ip
        WHERE ip.real_player_tier = 'legend'
          AND ip.id NOT IN (SELECT player_id FROM player_share_markets)
        ON CONFLICT (player_id) DO NOTHING;
    """)

    op.execute("""
        UPDATE player_share_markets
        SET total_shares = GREATEST(1, COALESCE(circulating_shares, 0)),
            released_shares = GREATEST(1, COALESCE(circulating_shares, 0)),
            status = 'active',
            share_price_coin = ROUND(250.0 * POWER(ip.governed_gsi / 90.0, 3.2) * 3.6, 2),
            updated_at = NOW()
        FROM ingestion_players ip
        WHERE player_share_markets.player_id = ip.id
          AND ip.real_player_tier = 'legend';
    """)

    # 7. Synchronize player_summary_read_models for all authentic legends
    op.execute("""
        UPDATE player_summary_read_models rm
        SET summary_json = (
            COALESCE(rm.summary_json::jsonb, '{}'::jsonb) || jsonb_build_object(
                'real_player_tier', 'legend',
                'is_legend', true,
                'total_shares', GREATEST(1, COALESCE((rm.summary_json->>'circulating_shares')::int, psm.circulating_shares, 0)),
                'released_shares', GREATEST(1, COALESCE((rm.summary_json->>'circulating_shares')::int, psm.circulating_shares, 0)),
                'circulating_shares', COALESCE((rm.summary_json->>'circulating_shares')::int, psm.circulating_shares, 0),
                'gsi', ip.governed_gsi,
                'overall', ip.governed_gsi,
                'global_scouting_index', ip.governed_gsi,
                'potential', ip.governed_potential_gsi,
                'is_tradable', true,
                'share_price_coin', COALESCE(psm.share_price_coin, (rm.summary_json->>'share_price_coin')::numeric, 50.0)
            )
        )::json,
        current_value_credits = COALESCE(psm.share_price_coin::float8, rm.current_value_credits),
        average_rating = ip.governed_gsi::float8,
        updated_at = NOW()
        FROM ingestion_players ip
        LEFT JOIN player_share_markets psm ON psm.player_id = ip.id
        WHERE rm.player_id = ip.id
          AND ip.real_player_tier = 'legend';
    """)


